    pred = None
    norm = 0.0
    for weight, estimator in zip(self.estimator_weights_, self.estimators_):
        norm += weight
        current_pred = np.where((estimator.predict(X) == classes).T, weight, -1 / (n_classes - 1) * weight)
        if pred is None:
