    r = re.compile('\\A(?P<before>({single_quoted}|{double_quoted}|{not_quoted})*)(?P<after>{char}.*)\\Z'.format(not_quoted=f"""[^"'{re.escape(characters)}]""", char=f'[{re.escape(characters)}]', single_quoted="('([^'\\\\]|(\\\\.))*')", double_quoted='("([^"\\\\]|(\\\\.))*")'))
    m = r.match(line)
    if m:
        d = m.groupdict()
        return (d['before'], d['after'])
    return (line, '')

